<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';
require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Core/WorkflowHelpers.php';require dirname(__DIR__).'/app/Services/Authorization.php';
Security::sendSecurityHeaders($config);Security::startSession($config);
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}
if(!Security::enforceAuthenticatedSession($config)||!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);exit('Session expired. Please sign in again.');}
try{$db=Database::connection();$user=Authorization::user($db,(int)$_SESSION['user_id']);if(!$user)throw new RuntimeException('Authentication required.');$admin=$user['role_code']==='BARANGAY_ADMINISTRATOR'&&Authorization::can($db,$user,'dashboard.admin.view');$id=(int)($_POST['transaction_id']??0);if($id<1)throw new InvalidArgumentException('Invalid transaction.');$db->beginTransaction();$q=$db->prepare('SELECT created_by,module_type,current_status FROM service_transactions WHERE transaction_id=:id FOR UPDATE');$q->execute(['id'=>$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new InvalidArgumentException('Transaction not found.');if(!$admin&&((int)$r['created_by']!==(int)$user['user_id']||$r['current_status']!=='SUBMITTED')){http_response_code(403);throw new RuntimeException('You may cancel only your own pending transaction.');}if($r['current_status']==='CANCELLED')throw new InvalidArgumentException('This transaction is already cancelled.');$u=$db->prepare("UPDATE service_transactions SET current_status='CANCELLED',reviewed_by_user_id=:uid,review_notes=:note,updated_at=NOW() WHERE transaction_id=:id");$u->execute(['uid'=>$user['user_id'],'note'=>$admin?'Cancelled by administrator.':'Cancelled by account holder while pending.','id'=>$id]);$h=$db->prepare('INSERT INTO service_status_history (transaction_id,old_status,new_status,notes,changed_by_user_id) VALUES (:id,:old,\'CANCELLED\',:notes,:uid)');$h->execute(['id'=>$id,'old'=>$r['current_status'],'notes'=>$admin?'Administrator cancellation':'User cancellation of pending request','uid'=>$user['user_id']]);AuditLogger::record($db,(int)$user['user_id'],$admin?'ADMIN_TRANSACTION_CANCELLED':'USER_TRANSACTION_CANCELLED','service_transaction',$id,['old_status'=>$r['current_status'],'module_type'=>$r['module_type']]);$db->commit();header('Location: dashboard.php?updated=1#transactions');exit;}catch(Throwable $e){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();error_log('Cancel transaction: '.$e->getMessage());http_response_code(422);exit(Security::e($e->getMessage()));}
